insert into public.evaluation_entries(subject,author,body,sort_order) values
  ('서성준', '이다경', '체력 무한대임!!!! 같이 있으면 웃기고, 둘이 있으면 진지한 대화도 할 줄 아는 사람임. 최고의 팀장 ㅎㅎ', 1),
  ('서성준', '이은비', '언제나 활발하고 에너지가 넘침. 모두가 힘들어할 때도 항상 웃고 있어서 보고 있는 사람도 힘이 남. 모든 운동을 두루두루 잘해서 신기함. 재미있음. 시고르자브종 같음.', 2),
  ('서성준', '김학진', '높은 텐션의 소유자임. 누구와 있어도 어색할 것 같지 않은 친화력이 있음. 그래도 진지해야 할 때는 진지하고, 주변 사람들을 잘 챙기는 세심함이 있음. 가끔 감당이 안 될 정도로 텐션이 올라감.', 3),
  ('서성준', '은태경', '순모임이나 회의 때 분위기를 재밌고 편안하게 만드는 능력이 되게 부럽고 대단함..🫢 또 평소엔 장난기가 많은데, 회의나 프로그램을 진행할 땐 누구보다 신중하고 책임감을 다해 임하는 모습이 너무 멋있음 ㅎㅎ 그리고 편지 써준 거 진짜 감동,,,&,&,,,', 4),
  ('서성준', '한은혜', '본 사람 중 가장 NF 같음. 안 지치는 체력의 원동력이 궁금할 정도로 항상 팔딱거림. 매번 학교에선 이렇게 안 한다고 하지만 어딜 나가서도 같은 성격일 것 같음. 페르소나가 없는 모습이 부러운데 그 모습이 늘 긍정적인 것처럼 보여서 부러움. 취미가 많아 보이는데 적당히 할 거 던져 주면 일주일 동안 혼자서도 잘 놀 것 같음. 건강해 보임.', 5),
  ('서성준', '서성준', '잘생기고 똑똑하고 배려심 넘치고 마음이 넓고 운동도 잘하는데 귀엽기까지 하고 성실하고 진정한 이 시대의 7의 남자임.', 6),
  ('서성준', '최민규', '매우 활발함. 주변 사람을 잘 웃게 만드는 능력이 있음. 정이 많음. 이다경을 자주 놀리는 편임. 춤은 못 추지만 흥이 나면 춤을 자주 춤. 운동의 경우 종목을 가리지 않고 매우 잘함. 요즘 저글링을 배워서 자주 저글링을 함. 박수 쳐주면 신나함.', 7),
  ('최민규', '이다경', '따스하고 사람을 참 잘 챙기고 다재다능한 팔방미인인 사람임.', 1),
  ('최민규', '이은비', '최고의 게임 친구임!!! 맨날 화장실 감… 고민 상담을 잘해줌. 공을 엄청 좋아함. 저글링을 잘함. 솜브라 장인임. 의지할 수 있음.', 2),
  ('최민규', '김학진', '평소에는 잔잔하지만 팀장님과 있으면 시너지가 극대화됨. 여러 부분에서 다재다능한 사람임. 다른 사람의 고민을 진지하게 들어주고 필요한 말을 잘해줌. 게임을 사랑하는 남자임. 자유투 내기 꼴찌.', 3),
  ('최민규', '은태경', '인도도 잘하고 드럼도 잘 치고 기타도 잘 치고 사진, 영상도 잘 찍고 심지어 편집까지 함… 완전 다재다능한 육각형 사람🫣 근데 반전 매력으로 포켓몬을 좋아하는 걸 넘어 사랑하는 듯..? ㅋㅋㅋㅋㅋ 주변 사람들을 되게 잘 챙기고, 가끔씩 전화로 응원과 격려를 해줄 때 정말 힘이 되고 감동받음ㅎㅎ 항상 감사하고 존경함&_&', 4),
  ('최민규', '한은혜', '항상 얘기를 해보면 주위에 좋은 사람들이 많아서 감사하다는 소리를 많이 하는 것 같은데, 그렇다고 느낄 수 있고 표현할 수 있다는 점이 어른스럽게 느껴짐. 폼을 본인이 만들었을 것 같아서 그렇게 칭찬해 주고 싶지는 않은데… 여튼 항상 감사할 줄 아는 사람인 것 같음. 예의를 중요시하고 쉽게 곁을 주지 않(는다고 하는데 생각보다 사람을 너무 좋아하는 것 같)음.', 5),
  ('최민규', '서성준', '드럼 잘 패는 남자임.', 6),
  ('최민규', '최민규', '조용한 곳을 좋아하지만 친한 사람들과 같이 있을 때에는 활발한 편임. 노래 부르는 것을 좋아함. 기타를 칠 줄 앎. 드럼을 칠 줄 앎. 세컨을 칠 줄 앎.', 7),
  ('한은혜', '이다경', '시크함 속에 묻어나오는 챙김으로 두근거리게 하는 사람임. 안으면 따뜻하고 포근함.', 1),
  ('한은혜', '이은비', '사람들을 잘 챙겨줌. 꼼꼼하게 정리를 잘함. 춤을 너무너무 잘 춤. 노래 잘 부름. 선택하는 단어들이 재미있음. 카페 가는 거 좋아함. 한교동. 먼지 알러지가 있음.', 2),
  ('한은혜', '김학진', '누구에게나 친근하게 다가감. 작은 일에도 대충 넘기지 않는 꼼꼼함을 가지고 있음. 평소 텐션이 높지만 졸리면 동태눈깔이 나옴. 교수님의 노예임.', 3),
  ('한은혜', '은태경', '걸크러쉬하고 예쁨. 대학원에서 배터리 터트리느라 바쁜 와중에도 인스타 게시물도 만들고 워십도 준비하고 체력과 책임감이 대단한 사람임.. 항상 보컬로 음향으로 워십으로 다양한 모습으로 열심히 하는 모습이 되게 멋있고 롤모델임 ㅎㅎ 또 특유의 리더십으로 이끌고, 본인만의 방식으로 주변 사람들에게 위로와 힘을 주는 게 대단하고 짱임 ㅋㅋㅋㅋㅋㅋㅋ 아자아자🫡', 4),
  ('한은혜', '한은혜', '현생에 지쳐 있는 이에스티제이 기계공학과 김동규 교수 따까리임.', 5),
  ('한은혜', '서성준', '춤 잘 추는 여자임.', 6),
  ('한은혜', '최민규', '부산스럽거나 소란스러운 것을 선호하지 않지만 같이 있을 땐 나름 즐거워하는 것 같음. 총무팀에서 가장 힘이 강함. 춤을 매우 잘 춤. 표현이 많진 않지만 정이 많고 주변 사람들을 잘 챙겨줌. 겉으로는 분명 꼼꼼해 보이지만 상당히 덜렁댐. 움직이는 종합병원임.', 7),
  ('이다경', '이다경', '귀엽고 깜찍하고 사랑스럽고 아름다운 사람임.', 1),
  ('이다경', '이은비', '노래를 너무너무 잘함. 힘이 짱 셈. 리트리버 같아서 귀여움. 항상 다정하게 웃어줌. 예쁨. 손을 잘 잡아주고 잘 안아줌. 잘 움.', 2),
  ('이다경', '김학진', '여러 가지 매력이 많은 사람임. 웃음이 많고 분위기를 즐겁게 만들어줌. 겉모습과 성격이 완전히 일치함. 보고 있으면 대단하다고 느껴지는 텐션을 가짐. 가끔 남자라고 느껴질 때가 있음.', 3),
  ('이다경', '은태경', '주변 사람들에게 선한 영향력을 주는 사람임! 보고 있으면 기분도 좋아지는 느낌.. 평소에 힘들거나 고민 있으면 찾게 되는 매력을 가졌음. 진짜 좋은 사람이어서 주변에도 항상 좋은 사람들이 가득함! ㅎㅎ 주변 사람들 챙기느라 자기 자신을 못 챙기는 느낌이어서 항상 본인을 가장 먼저 챙기면 좋겠음. 화이팅!!', 4),
  ('이다경', '한은혜', '동생임. 근데 진지해야 할 때는 주는 무게감이 있어서 가끔은 어른이구나(맞음) 싶음. 똑부러지지만 마음이 많이 여리고 감정에 솔직한 것 같음. 감정적이라는 말이 주로 좋은 뜻으로 쓰이지는 않는데, 감정적인 성격은 자기가 겪은 일이나 느낀 마음에 대해서 잘 풀어내고 진솔하게 말할 줄 아는 하나의 무기인 것 같음.', 5),
  ('이다경', '서성준', '노래 잘 부르는 여자임 (살짝 애매함).', 6),
  ('이다경', '최민규', '활발함. 귀여운 구석이 있음. 서성준에게 자주 놀림받는 편임. 꽤 춤을 잘 추며 평소에 흥이 나면 춤을 춤. 노래를 매우 잘 부름. 털털한 성격임. 자주 우는 편임. 주변 사람들의 칭찬을 받으면 흡족스러워함. 친한 사람들 앞에서는 부끄러움을 크게 타지 않음.', 7),
  ('김학진', '이다경', '겉으로 드러나지 않는 따뜻함이 느껴지는 사람임. 깊게 알아가면 숨은 매력이 넘쳐날 것 같음.', 1),
  ('김학진', '이은비', '아재개그를 좋아함… 조용한데 웃김. 감동이 있음. 장난을 잘 받아줌. 누구에게나 친절함. 너무 착함. 게임을 잘함. 가끔 빙구처럼 웃음. 화를 잘 안 냄. 처음에 낯을 가림. 친해지면 말이 많음.', 2),
  ('김학진', '김학진', '평소 조용한 성격임. 친해지기까지 오래 걸리지만 친해지면 생각보다 이상함. 한다면 하는 남자라는 타이틀을 가지고 있음.', 3),
  ('김학진', '은태경', '언제부터인가 총무팀과 함께하고 있음 ㅋㅋㅋㅋㅋㅋ 근데 힘든 티도 안 내고 묵묵히 해내고 있는 게 웃기면서도 대단함.. 처음엔 뭔가 놀리려고? 같이 하는 줄 알았는데 조명 설치하는 법도 배우고 회의도 참여하고 알고 보면 총무팀을 좋아하는 듯ㅎ 그리고 장난치는 것도 다 받아주고 보기보다 재밌음. 내년 총무팀이니까 같이 힘내자~<', 4),
  ('김학진', '한은혜', '한다면 하는 남자. 차기 총무팀. 찰리. 겜돌이. 조용히 할 말 다 하는 친구임. 이은비랑 싸우지 말고 사이좋게 지내야 함~', 5),
  ('김학진', '서성준', '귀여움ㅎ', 6),
  ('김학진', '최민규', '매우 조용하지만 잘 웃는 편임. 쉽게 화를 내지 않음. 안정형 남친의 정석임. 잔잔하게 던지는 한마디가 상당히 웃김. 모든 게임을 잘함. 게임하다 놀라면 외마디로 소리 지름. 한다면 하는 남자, XX 김학진 선생. 이은비와 매우 친함. 찰리.', 7),
  ('은태경', '이다경', '사람을 좋아하고 넘치는 사랑을 주며 따뜻하게 챙겨주는 귀여운 강아지 같은 사람임. 포기를 모르는 사람임.', 1),
  ('은태경', '이은비', '누구든지 금방 친해짐. 친화력 최고! 잘 움. 물건을 잘 빌려줌. 같이 놀면 재미있음. 키가 2m 조금 안 됨. 항상 잘 챙겨줌. 알바를 많이 함. 노는 거 좋아함.', 2),
  ('은태경', '김학진', '첫인상과 매우 다름. 겉으로 보이는 모습과 실제 성격에 차이가 있음. 처음 보는 사람과도 금방 친해질 정도로 친화력이 좋음. 친구가 당황해하는 모습을 보면 행복해하는 경향이 있음.', 3),
  ('은태경', '은태경', '🤔', 4),
  ('은태경', '한은혜', '이번 연도 초까지는 여전히 고등부 학생처럼 느껴졌는데 시간이 지나니 그런 느낌은 전혀 없어짐. 자기가 해야 할 일에는 몰두할 줄 아는 것 같음. 뭘 해야 한다고 하면 선뜻 바로 나와줄 수 있을 정도로 총무팀에 잘 녹아든 것 같아서 기특함. 마음이 여리고 몸도 여려서 부러질 것 같아서 그간 많이 못 놀려먹었는데 이제는 충분히 익숙해진 것 같아서 마음 놓고 놀려먹을 예정임. 제자교회 세컨맨 파이팅.', 5),
  ('은태경', '서성준', '피아노 잘 치는 여자임.', 6),
  ('은태경', '최민규', '세컨을 잘 침. 요즘은 메인 건반도 섭렵하기 위해 야망을 품고 연습하는 중임. 잘 우는 편임. 좋아하는 일에 대한 열정이 넘치고 끈기가 있음. 사람을 매우 좋아하고 사교성이 엄청남. 때리면 부러질 것 같아서 자주 못 때렸는데 앞으로는 시도해볼 예정임.', 7),
  ('이은비', '이다경', '수달. 뻥이고 맡은 바 책임을 묵묵히 다하는 사람임. 모든 사람에게 배려 가득한 행동과 말을 해주는 사람임.', 1),
  ('이은비', '이은비', '하핳', 2),
  ('이은비', '김학진', '자신이 맡은 일을 성실히 해내는 성격임. 다른 사람의 이야기를 잘 들어주고 공감을 잘해줌. 사람을 놀리는 데에 진심임. 겉보기엔 순하지만 싸이코패스 기질이 있음.', 3),
  ('이은비', '은태경', '일단 너무 호감상임.. (부러워) 중고등부 애들한테 되게 웃으면서 다가가고 장난도 적당히 기분 좋을 만큼 치고 진짜 딱 호감형 사람의 정석임,, 비투 때 방도 같이 쓰고 수련회 때 많이 얘기하면서 항상 느끼는 거지만 참 상대방이 듣고 싶어 하는 말들을 정확히 얘기해주는 능력이 대박임😮 그리고 밤마다 최민규랑 김학진이랑 게임했다는 얘기 들어보면 되게 행복해 보임 ㅋㅋㅋㅋㅋ 한 줄로 말하면 그림과 게임을 좋아하는 호감형 사람임!!', 4),
  ('이은비', '한은혜', '뭐 하자고 하면 다 알겠다고 해줄 예스맨. 한다면 하는 여자 이은비…. 겜돌이. 제자교회 베이스맨. 최민규한테 뺏긴 워십 가능자…. 워낙에 모난 곳 없고 둥글둥글 성격이 좋아서 오히려 많이 시달리는 듯함. 노는 걸 좋아하고 사람도 좋아하는 듯함. 최민규가 왜 이렇게 학생 때부터 끌고 다녔는지 알 것 같음. 어떤 일이 있더라도 믿고 맡길 수 있는 친구임. 김학진이랑 싸우지 말고 사이좋게 지내야 함~', 5),
  ('이은비', '서성준', '베이스 잘 치는 여자임.', 6),
  ('이은비', '최민규', '소란스러움. 웃음이 많고 털털한 성격임. 김학진과 매우 친함. 발로란트 선생님. 베이스를 잘 침. 주변에 있으면 자주 웃게 됨. 타인에게는 관대하지만 스스로에게 비교적 엄격한 편임. 자신이 낯을 많이 가린다고 하지만 붙임성이 매우 좋음.', 7)
